import json,sys,shutil
from pathlib import Path
sys.dont_write_bytecode=True
from model import Arithmetic, ext80, digest, synthetic
R=Path(__file__).resolve().parent.parent
W=Path(sys.argv[1]).resolve();ROOT=Path(sys.argv[2]).resolve()
def put(p,v):(R/p).write_text(json.dumps(v,indent=2,sort_keys=True)+'\n')
x=json.loads((W/'results.json').read_text());comparisons=[]
for p in sorted(W.glob('*.comparison.json')):comparisons.append({'case':p.name.removesuffix('.comparison.json'),**json.loads(p.read_text())})
for src,dst in [('audit.json','evidence/arithmetic_audit.json'),('dependencies.json','evidence/unserviced_imports.json'),('gamma-cw-control.json','evidence/gamma_cw_control.json'),('tests.txt','evidence/standalone_tests.txt')]:shutil.copyfile(W/src,R/dst)
base=(W/'permuted-037f-0.gamma').read_bytes();fixtures=[]
for c in x['cases']:
    key=c['case'];b=(W/(key+'.gamma')).read_bytes();c['gamma_delta_from_pc64_double']=sum(a!=v for a,v in zip(base,b))
    c['gamma_difference_samples']=[{'offset':i,'baseline':a,'case_value':v} for i,(a,v) in enumerate(zip(base,b)) if a!=v][:12]
    if key.startswith('permuted'):
        a=Arithmetic(c['cw']);tr=(W/(key+'.gamma.power')).read_bytes()
        for slot,v in [(3,1),(3,33),(3,35),(3,254),(3,255),(1,255)]:
            off=((slot-1)*256+v)*30;power=ext80(tr[off+20:off+30]);scaled=a.op(power*255)
            fixtures.append({'case':key,'slot':slot,'component':v,'power_return_ext80_le':tr[off+20:off+30].hex(),'scaled_exact':str(scaled),'truncated':int(scaled),'stored_byte':b[(slot-1)*256+v]})
corpus=json.loads((R.parents[3]/'agent/runs/i76exe/i76exe-20261104T224244Z-4359bae0/evidence/corpus.json').read_text());retail=[]
for n in ['m05','m15','t01']:
    rec=next(r for r in corpus['resources'] if r['name']==n+'.lum');raw=(ROOT/'zfs/resources'/(n+'.lum')).read_bytes();assert digest(raw)==rec['sha256']
    generated=(W/(n+'-037f-0.lum')).read_bytes();retail.append({'resource':n+'.lum','resource_sha256':digest(raw),'generated_sha256':digest(generated),'different_bytes':sum(a!=b for a,b in zip(raw,generated)),'qualification':'Installed unmodified ACT in synthetic context; no callback normalization/correction. Difference does not establish authoring provenance.'})
put('evidence/results.json',x);put('evidence/original_comparisons.json',comparisons);put('evidence/differential_fixtures.json',{'gamma_thresholds':fixtures,'lum_variants':x['counterfactuals'],'precision':x['precision_examples'],'retail_lum_comparison':retail,'synthetic_palette_recipe':'scripts/model.py:synthetic; authored RGB8, not extracted assets'})
